const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const message = String(body.message || body.text || body.request || '').trim();
const lower = message.toLowerCase();
const chatId = body.chat_id || 'local-project-chat';
const state = body.conversation_state || {};
const availableTime = String(body.available_time || body.availableTime || state.available_time || 'unknown');
const preferredMode = String(body.preferred_mode || body.preferredMode || state.preferred_mode || 'any');
const maxOptions = Math.min(Number(body.max_options || body.maxOptions || 3), 3);
const dryRun = body.dry_run === true;
const idMatch = message.match(/\b(HU|EN|EXP|SP|T)-[A-Z0-9]+-\d+\b/i);
const backlogId = body.backlog_id || body.backlogId || state.selected_backlog_id || (idMatch ? idMatch[0].toUpperCase() : null);
const approveWords = ['apruebo', 'aprobado', 'confirmo', 'confirmado', 'ejecuta', 'ejecutar', 'continua', 'continúa', 'sigue', 'dale', 'si', 'sí', 'sii', 'listo'];
const hasApproval = body.approved === true || approveWords.some((word) => lower.includes(word));

const intents = [
  { name: 'knowledge', agent: 'project-knowledge', route: 'AGENT-KNOW-001', match: /\b(que sabemos|qué sabemos|contexto|fuente|fuentes|referencia|referencias|decision registrada|decisión registrada|donde esta|dónde está|donde encuentro|historial|contradiccion|contradicción|baseline|documentado)\b/i },
  { name: 'backlog', agent: 'project-backlog', route: 'AGENT-BKL-001', match: /\b(backlog|recomienda siguiente trabajo|siguiente trabajo|que trabajo|qué trabajo|tomar ahora|trabajar ahora)\b/i },
  { name: 'planning', agent: 'project-planning', route: 'AGENT-PLAN-001', match: /\b(planificar|planea|planning|roadmap|fase|fases|plan del proyecto|estado actual)\b/i },
  { name: 'refinement', agent: 'project-refinement', route: 'AGENT-REF-001', match: /\b(refinar|refinamiento|desglosar|granular|criterios de aceptacion|criterios de aceptación|dor|dod|hu|historia|enabler|spike|experiment|task)\b/i },
  { name: 'qa_evidence', agent: 'project-qa-evidence', route: 'AGENT-QA-001', match: /\b(evidencia|qa|prueba|validacion|validación|test|done|verificar|vv|v&v)\b/i },
  { name: 'architecture', agent: 'project-architecture', route: 'AGENT-ARCH-001', match: /\b(arquitectura|decision tecnica|decisión técnica|diseño tecnico|diseño técnico|contrato|mqtt|api|integracion|integración)\b/i },
  { name: 'engineering', agent: 'project-engineering', route: 'AGENT-ENG-001', match: /\b(codigo|código|implementar|programar|desarrollar|fix|bug|web|frontend|backend|firmware|sensor)\b/i },
  { name: 'safety_review', agent: 'project-reviewer-safety', route: 'AGENT-REV-001', match: /\b(riesgo|seguridad|review|revision|revisión|aprobar|permiso|bloqueo)\b/i }
];

let intent = intents.find((candidate) => candidate.match.test(message));
if (!intent) {
  intent = { name: 'pmo', agent: 'project-pmo', route: 'AGENT-PMO-001' };
}
if ((lower.includes('prioridad') || lower.includes('wip') || lower.includes('kanban') || lower.includes('desbloque')) && !['refinement', 'backlog'].includes(intent.name)) {
  intent = { name: 'pmo', agent: 'project-pmo', route: 'AGENT-PMO-001' };
}

const executionGuard = intent.name === 'engineering'
  ? 'Si la solicitud pide modificar codigo, primero verifica que exista HU/tarea refinada, alcance claro, aprobacion humana explicita y evidencia esperada. Si falta algo, no propongas editar: pide el paso faltante. En este runner responde DRAFT/read-only.'
  : 'Trabaja en modo DRAFT. Persistencia, cambios de backlog, cambios de Kanban, escrituras de archivos y ejecucion fisica requieren aprobacion humana/n8n.';

const prompt = [
  `Actua como ${intent.route} (${intent.agent}) para el proyecto Invernadero Central.`,
  'Tu alcance esta estrictamente limitado al proyecto: sensores, edge, datos, web, n8n, agentes, backlog, Kanban, roadmap, evidencia, arquitectura, mercado/growth documentado y decisiones versionadas.',
  'Si el humano pregunta algo fuera del proyecto, responde brevemente que solo puedes ayudar con el proyecto y ofrece una forma de reformularlo dentro del contexto del proyecto.',
  `Mensaje humano: ${message || '(vacio)'}.`,
  `chat_id: ${chatId}.`,
  `conversation_state: ${JSON.stringify(state)}.`,
  `intent_detected: ${intent.name}.`,
  `backlog_id_detected: ${backlogId || 'none'}.`,
  `human_approval_detected: ${hasApproval}.`,
  `Tiempo disponible humano: ${availableTime}.`,
  `Modo preferido: ${preferredMode}.`,
  `Maximo de opciones: ${maxOptions}.`,
  'Usa el contexto versionado del repo central y el baseline actual. Debes poder responder preguntas sobre estado del proyecto, backlog, roadmap, agentes, HUs, riesgos y siguiente mejor accion.',
  'Si debes enrutar a otro agente, dilo explicitamente en route.recommended_agent y explica por que.',
  executionGuard,
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no apruebes compras, no ejecutes despliegues criticos ni controles fisicos.',
  'Responde en espanol, sin emojis, con maximo 3 opciones cuando recomiendes trabajo, y haz una sola pregunta final si necesitas decision humana.',
  'Devuelve una respuesta util para mostrar directamente en el chat. Incluye route con recommended_agent, action_type y next_question si aplica.'
].join(' ');

return [{
  json: {
    agent: intent.agent,
    workspace: 'central',
    prompt,
    mode: 'chat-gateway',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'CHAT-GATEWAY-001',
      gateway_agent: 'AGENT-PMO-001',
      selected_agent: intent.route,
      selected_kiro_agent: intent.agent,
      intent: intent.name,
      backlog_id: backlogId,
      human_approval_detected: hasApproval,
      chat_id: chatId,
      available_time: availableTime,
      preferred_mode: preferredMode,
      max_options: maxOptions,
      scope: 'project_only'
    }
  }
}];

const runner = items && items[0] && items[0].json ? items[0].json : {};
const stripAnsi = (value) => String(value || '').replace(/\u001b\[[0-9;?]*[ -/]*[@-~]/g, '').trim();
const stripToolLogs = (value) => {
  let text = stripAnsi(value);
  const markers = ['## ', '### ', 'DRAFT', 'route:', 'recommended_agent:', 'Respuesta:', 'Estado actual', 'Recomendacion', 'Recomendación'];
  const positions = markers.map((marker) => text.indexOf(marker)).filter((index) => index >= 0);
  if (positions.length > 0) {
    text = text.slice(Math.min(...positions)).trim();
  }
  return text
    .split('\n')
    .filter((line) => !/^Batch fs_read operation/.test(line))
    .filter((line) => !/^↱ Operation/.test(line))
    .filter((line) => !/^ ✓ Successfully read/.test(line))
    .filter((line) => !/^ ⋮ /.test(line))
    .filter((line) => !/^- Summary:/.test(line))
    .filter((line) => !/^ - Completed/.test(line))
    .filter((line) => !/^Reading file:/.test(line))
    .filter((line) => !/^> /.test(line))
    .join('\n')
    .trim();
};
const stdout = stripToolLogs(runner.stdout);
const stderr = stripAnsi(runner.stderr);
const reply = stdout || (runner.dry_run ? 'Gateway validado en dry_run. El chat esta conectado al agente seleccionado.' : 'No recibi salida util del agente.');

return [{
  json: {
    status: runner.status || 'UNKNOWN',
    chat_scope: 'project_only',
    reply,
    route: {
      workflow: 'CHAT-GATEWAY-001',
      gateway_agent: 'AGENT-PMO-001',
      primary_agent: runner.agent || 'project-pmo',
      authority: 'A1',
      review_required: runner.requires_human_review !== false
    },
    constraints: [
      'Solo responder o trabajar con contexto del proyecto Invernadero Central.',
      'No modificar HU congeladas.',
      'No mover estados sin aprobacion humana.',
      'No marcar DONE sin evidencia.',
      'No aprobar compras, despliegues criticos ni control fisico.',
      'Hacer una sola pregunta al humano por turno.'
    ],
    runner: {
      dry_run: !!runner.dry_run,
      exit_code: runner.exit_code,
      duration_ms: runner.duration_ms,
      auth_source: runner.auth && runner.auth.source,
      error: runner.error || null,
      stderr
    }
  }
}];
